    // Sync to clock for deterministic behavior
    @(negedge Clk);

    // -------------------------------------------------------
    // Test Case 1: Reset Verification
    // -------------------------------------------------------
    // Assert Reset
    Rst = 1'b1;
    EN = 1'b1;
    @(negedge Clk);
    // Expect: EMPTY=1, FULL=0, SP=4

    // -------------------------------------------------------
    // Test Case 2: Enable Low (Write should be ignored)
    // -------------------------------------------------------
    Rst = 1'b0;
    EN = 1'b0;
    RW = 1'b0; // Write mode
    dataIn = 4'hA;
    @(negedge Clk);
    @(negedge Clk); // Hold to ensure no write happens
    // Expect: No change, EMPTY=1

    // -------------------------------------------------------
    // Test Case 3: Sequential Push (Fill Stack)
    // -------------------------------------------------------
    EN = 1'b1;
    RW = 1'b0; // Write

    // Push 0x1 (SP -> 3)
    dataIn = 4'h1;
    @(negedge Clk);

    // Push 0x2 (SP -> 2)
    dataIn = 4'h2;
    @(negedge Clk);

    // Push 0x4 (SP -> 1)
    dataIn = 4'h4;
    @(negedge Clk);

    // Push 0x8 (SP -> 0)
    dataIn = 4'h8;
    @(negedge Clk);

    // Stack should be FULL now (SP=0)

    // -------------------------------------------------------
    // Test Case 4: Overflow Protection
    // -------------------------------------------------------
    // Try to push 0xF into FULL stack
    dataIn = 4'hF;
    @(negedge Clk);
    // Expect: FULL=1, Internal Memory[0] should still be 0x8

    // -------------------------------------------------------
    // Test Case 5: Sequential Pop (Empty Stack)
    // -------------------------------------------------------
    RW = 1'b1; // Read

    // Pop (Expect 0x8, SP -> 1)
    @(negedge Clk);

    // Pop (Expect 0x4, SP -> 2)
    @(negedge Clk);

    // Pop (Expect 0x2, SP -> 3)
    @(negedge Clk);

    // Pop (Expect 0x1, SP -> 4)
    @(negedge Clk);

    // Stack should be EMPTY now (SP=4)

    // -------------------------------------------------------
    // Test Case 6: Underflow Protection
    // -------------------------------------------------------
    // Try to pop from EMPTY stack
    @(negedge Clk);
    // Expect: EMPTY=1, SP=4

    // -------------------------------------------------------
    // Test Case 7: Interleaved Operations & Data Patterns
    // -------------------------------------------------------
    RW = 1'b0; // Write

    // Push 0xA (Alternating 1010)
    dataIn = 4'hA;
    @(negedge Clk);

    // Push 0x5 (Alternating 0101)
    dataIn = 4'h5;
    @(negedge Clk);

    // Switch to Read
    RW = 1'b1;
    // Pop 0x5
    @(negedge Clk);

    // Switch to Write
    RW = 1'b0;
    // Push 0xC (1100)
    dataIn = 4'hC;
    @(negedge Clk);

    // -------------------------------------------------------
    // Test Case 8: Reset during operation
    // -------------------------------------------------------
    Rst = 1'b1;
    @(negedge Clk);
    // Expect: EMPTY=1, FULL=0, SP=4
    Rst = 1'b0;
    @(negedge Clk);

    // -------------------------------------------------------
    // Test Case 9: Boundary Values (0 and F)
    // -------------------------------------------------------
    RW = 1'b0; // Write
    dataIn = 4'h0;
    @(negedge Clk);

    dataIn = 4'hF;
    @(negedge Clk);

    RW = 1'b1; // Read
    @(negedge Clk); // Pop F
    @(negedge Clk); // Pop 0

    // 4. Cleanup / Handover
    #20;
    llm_go_signal = 0;
end
// ============================================


